const ids = ["folder:159d84b7cec4a38c","jira:SYN-3","jira:SYN-47","jira:SYN-61","jira:SYN-45"];
const r = [];
for (const id of ids) { const i = await items.read(id as any); r.push(i.gone ? i : {title:i.title, text:i.text}); }
return r;

